def find_path(graph, start, goal):

    def explore(current_node, goal, path=None):
        if path is None:
            path = [current_node]
        if current_node == goal:
            return path
        for neighbor in graph.get(current_node, []):
            if neighbor not in path:
                new_path = explore(neighbor, goal, path + [neighbor])
                if new_path:
                    return new_path
        return None
    return explore(start, goal)

